#include <iostream>
#include <stdexcept>

class OrderRejected : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

void report(int which) {
    try {
        if (which == 0) {
            throw OrderRejected{"rejected"};
        }
        throw std::runtime_error{"runtime"};
    } catch (const std::runtime_error& error) {
        std::cout << "runtime handler: " << error.what() << '\n';
    } catch (const OrderRejected& error) {
        std::cout << "reject handler: " << error.what() << '\n';
    }
}

int main() {
    report(0);
    report(1);
}

