#include <stdexcept>

struct Order {
    int requested_quantity;
    int filled_quantity;
    double filled_notional;
};

struct Fill {
    int quantity;
    double price;
};

void apply_fill(Order& order, Fill fill) {
    // Prepare: all potentially throwing work happens on the side, in locals.
    const int next_quantity = order.filled_quantity + fill.quantity;
    const double next_notional =
        order.filled_notional + fill.quantity * fill.price;

    // Validate: the only exit that throws is reached before any mutation.
    if (next_quantity > order.requested_quantity) {
        throw std::runtime_error{"overfill"};
    }

    // Commit: from here on nothing can throw, so the transition is atomic
    // with respect to exceptions.
    order.filled_quantity = next_quantity;
    order.filled_notional = next_notional;
}

struct ScopeExit {
    void (*action)() noexcept;
    bool active = true;

    ~ScopeExit() noexcept {
        if (active) {
            action();
        }
    }

    void dismiss() noexcept {
        active = false;
    }
};

void begin_book_update();
void apply_book_change();
bool book_is_valid();
void commit_book_update() noexcept;
void rollback_book_update() noexcept;

bool update_book() {
    begin_book_update();
    ScopeExit rollback{rollback_book_update};

    apply_book_change();
    if (!book_is_valid()) {
        return false;  // guard still active: rollback runs
    }

    commit_book_update();
    rollback.dismiss();  // success: do not undo what we just committed
    return true;
}

#include <cstdint>
#include <expected>
#include <limits>
#include <string_view>

struct Price {
    std::int64_t ticks;
};

enum class ParseError {
    empty,
    invalid_character,
    overflow
};

[[nodiscard]] std::expected<Price, ParseError>
parse_price(std::string_view text) {
    if (text.empty()) {
        return std::unexpected(ParseError::empty);
    }

    std::int64_t value = 0;
    for (char character : text) {
        if (character < '0' || character > '9') {
            return std::unexpected(ParseError::invalid_character);
        }

        const std::int64_t digit = character - '0';
        const std::int64_t limit = std::numeric_limits<std::int64_t>::max();

        // Check before the multiply: signed overflow is undefined behavior,
        // so there is no wrapped result to inspect afterwards.
        if (value > (limit - digit) / 10) {
            return std::unexpected(ParseError::overflow);
        }

        value = value * 10 + digit;
    }

    return Price{value};
}

#include <exception>
#include <iostream>
#include <stdexcept>

class OrderRejected : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

void route_order();

void handle_order() {
    try {
        route_order();
    } catch (const OrderRejected& error) {
        // Derived first: handlers are tested in source order and the first
        // type match wins, so a base handler above this one would shadow it.
        std::cout << "reject: " << error.what() << '\n';
    } catch (const std::runtime_error& error) {
        std::cout << "runtime failure: " << error.what() << '\n';
    } catch (const std::exception& error) {
        std::cout << "standard exception: " << error.what() << '\n';
    } catch (...) {
        // An empty catch (...) {} would turn a known failure into unknown
        // state: the program continues with no idea what went wrong. A bare
        // `throw;` rethrows the original exception without changing its type
        // or slicing it.
        throw;
    }
}

#include <optional>

struct Config {
    bool endpoint_is_valid;
};

class Session {
public:
    // Infallible: by the time this runs, the Config has already been checked.
    explicit Session(const Config&) {}
};

// A constructor has no return channel, so fallible setup moves out here.
[[nodiscard]] std::optional<Session> open_session(const Config& config) {
    if (!config.endpoint_is_valid) {
        return std::nullopt;
    }
    return Session{config};
}

#include <cassert>
#include <cstdlib>
#include <iostream>

void send_order(int quantity, bool gateway_is_trusted) {
    // Internal invariant: callers inside this system are expected to have
    // validated the quantity already. Under NDEBUG this expression is removed
    // completely, which is fine for a development-time check -- and is exactly
    // why nothing with a required side effect may go inside an assert.
    assert(quantity > 0);

    // Trust boundary: this one must hold in the shipped build too, so it is an
    // ordinary always-on branch. Continuing on an untrusted gateway could send
    // real orders from corrupted state, which is worse than stopping.
    if (!gateway_is_trusted) {
        std::cerr << "untrusted gateway state\n";
        std::abort();
    }

    std::cout << "sent " << quantity << '\n';
}
